'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { Users } from 'lucide-react';

const ROLE_COLORS: Record<string, string> = {
    super_admin: '#7c3aed',
    admin: '#2563eb',
    hod: '#0891b2',
    faculty: '#059669',
    student: '#d97706',
};

export default function UsersPage() {
    const [users, setUsers] = useState<any[]>([]);

    useEffect(() => {
        const load = async () => {
            try {
                const res = await api.get<any[]>('/api/admin/users');
                if (res.success) setUsers(res.data);
            } catch (e) { }
        };
        load();
    }, []);

    return (
        <div>
            <h1 style={{ fontSize: 24, fontWeight: 700, color: '#142B34', fontFamily: 'Poppins', marginBottom: 8 }}>Users</h1>
            <p style={{ fontSize: 14, color: '#5a6a72', marginBottom: 24 }}>Manage all users in this institution</p>

            {users.length === 0 ? (
                <div className="card" style={{ textAlign: 'center', padding: 48, color: '#8a9aa2' }}>
                    <Users size={40} style={{ margin: '0 auto 12px', opacity: 0.3 }} />
                    <p>No users found</p>
                </div>
            ) : (
                <div className="table-container">
                    <table>
                        <thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th></tr></thead>
                        <tbody>
                            {users.map((u) => (
                                <tr key={u.id}>
                                    <td style={{ fontWeight: 600 }}>{u.name}</td>
                                    <td>{u.email}</td>
                                    <td>
                                        <span style={{
                                            fontSize: 11, fontWeight: 700, padding: '3px 10px',
                                            borderRadius: 4, background: `${ROLE_COLORS[u.role] || '#666'}15`,
                                            color: ROLE_COLORS[u.role] || '#666', textTransform: 'uppercase',
                                        }}>
                                            {u.role}
                                        </span>
                                    </td>
                                    <td><span className={`badge ${u.is_active ? 'badge-success' : 'badge-danger'}`}>{u.is_active ? 'Active' : 'Inactive'}</span></td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
    );
}
